# Add labels and title
plt.title('Dual Y-Values Chart', fontsize=16)
plt.xlabel('Index', fontsize=14)
plt.ylabel('Y Values', fontsize=14)

# Add a legend to differentiate the two Y-value series
plt.legend()

# Display grid for better readability
plt.grid(True, linestyle='--', alpha=0.5)

# Improve layout
plt.tight_layout()

# Show the plot
plt.show()
